css:
.print-format { padding: 0 !important; margin: 0 !important; }
.mi4 { width: 96mm; font-family: "DejaVu Sans Mono", "Courier New", monospace; font-size: 11px; line-height: 1.3; color: #000; }
.mi4 table { width: 100%; border-collapse: collapse; }
.mi4 td { padding: 0 1px; vertical-align: top; }
.mi4 .kv td:first-child { width: 38%; }
.mi4 .c { text-align: center; }
.mi4 .r { text-align: right; white-space: nowrap; }
.mi4 .b { font-weight: bold; }
.mi4 .big { font-size: 13px; }
.mi4 .rule { border-top: 1px dashed #000; margin: 4px 0; }

.mi4 .small td { font-size: 0.85em; }
.mi4 .sig { margin-top: 18px; }
.mi4 .sig td { padding-top: 14px; border-top: 1px solid #000; text-align: center; width: 45%; }
.mi4 .sig td.gap { border: 0; width: 10%; }
.mi4 .sec { margin-top: 4px; }

html:
{%- set cur = {"fieldtype": "Currency", "options": doc.currency or frappe.db.get_value("Company", doc.company, "default_currency")} -%}
{%- if not doc.is_return %}<div class="mi4"><div class="c b">{{ _("{0} is not a return note.").format(doc.name) }}</div></div>{% else -%}
{%- set f = mobile_return_note_print(doc) -%}
{%- set against = f.against | join(", ") -%}
<div class="mi4">
	<div class="c b big">{{ doc.company }}</div>
	{%- set tax_id = doc.get("company_tax_id") or frappe.db.get_value("Company", doc.company, "tax_id") %}
	{%- if tax_id %}<div class="c">{{ _("Tax ID") }}: {{ tax_id }}</div>{% endif %}
	<div class="c b">{{ _("RETURN NOTE") }}</div>
	<div class="rule"></div>
	<table class="kv">
		<tr><td>{{ _("No") }}</td><td>{{ doc.name }}</td></tr>
		<tr><td>{{ _("Date") }}</td><td>{{ frappe.format(doc.posting_date, "Date") }} {{ (doc.posting_time | string)[:5] }}</td></tr>
		<tr><td>{{ _("Customer") }}</td><td>{{ doc.customer_name }}</td></tr>
		{%- if f.agent_name %}<tr><td>{{ _("Agent") }}</td><td>{{ f.agent_name }}</td></tr>{% endif %}
		<tr><td>{{ _("Against") }}</td><td>{{ against or _("No invoice") }}</td></tr>
		{%- if f.visit %}<tr><td>{{ _("Visit") }}</td><td>{{ f.visit }}</td></tr>{% endif %}
	</table>
	<div class="rule"></div>
	<table class="items">
		<tr class="b"><td>{{ _("Item") }}</td><td class="r">{{ _("Qty") }}</td><td class="r">{{ _("Rate") }}</td><td class="r">{{ _("Amount") }}</td></tr>
		{%- for l in f.lines %}
		<tr><td colspan="4">{{ l.item_name }}</td></tr>
		<tr><td></td><td class="r">{{ frappe.format(l.qty, {"fieldtype": "Float"}) }} {{ l.uom }}</td><td class="r">{{ frappe.format(l.rate, cur) }}</td><td class="r">-{{ frappe.format(l.amount, cur) }}</td></tr>
		{%- if l.reason or l.condition %}
		<tr class="small"><td colspan="4">{{ l.reason or "" }}{% if l.condition %} · {{ _(l.condition) }}{% endif %}{% if l.remarks %} · {{ l.remarks }}{% endif %}</td></tr>
		{%- endif %}
		{%- endfor %}
	</table>
	<div class="rule"></div>
	<table class="kv totals">
		{%- if f.rounding %}
		<tr><td>{{ _("Lines") }}</td><td class="r">{{ frappe.format(f.lines_total, cur) }}</td></tr>
		<tr><td>{{ _("Rounding") }}</td><td class="r">{{ frappe.format(f.rounding, cur) }}</td></tr>
		{%- endif %}
		<tr class="b"><td>{{ _("Total credit") }}</td><td class="r">{{ frappe.format(f.credit, cur) }}</td></tr>
		{%- for p in f.applied %}
		<tr><td>{{ _("Credit applied to") }} {{ p.invoice }}</td><td class="r">{{ frappe.format(p.amount, cur) }}</td></tr>
		{%- endfor %}
		<tr class="b"><td>{{ _("Credit left on account") }}</td><td class="r">{{ frappe.format(f.credit_left, cur) }}</td></tr>
	</table>
	<div class="rule"></div>
	<table class="sig"><tr><td>{{ _("Customer") }}</td><td class="gap"></td><td>{{ _("Agent") }}</td></tr></table>
</div>
{%- endif %}
